-- Every inbox view shape a team's Zendesk-style views express reads a bounded number of rows on a large
-- workspace (src/modules/management/README.md, "Inbox reads at scale"). Like 313 every value is derived from the
-- inbox entries (and their custom field values): the migration fills it and triggers keep it current, so imports,
-- restores and erasure keep it true; a restore rebuilds it from the restored rows.
-- inbox_unread_tallies counts each member's unread entries (inbox_unread) by workspace, group, assignee and flags,
-- so the counts, the bootstrap and mark-as-read read a handful of rows instead of one per unread conversation.
-- inbox_facets holds one row per tag of an entry, per non-null custom field value (json_extract of value_json,
-- exactly the value a filter compares), per field an entry holds a non-null value of ('n': NULL when the value is
-- not the empty string, '' when it is) and per entry with more than eight tags, carrying the entry's group,
-- assignee, flags, ticket status columns, times, tags and inbox order, so a page of one tag or one field value
-- walks its rows in the page's order and reads one row per candidate.
-- inbox_counts counts entries by family key: every entry ('a'), each set of one to four of an entry's tags ('s',
-- entries with at most eight tags), each custom field value ('v') and field with any non-null value ('n'), and the
-- UTC year, month and day of created_at ('c') and updated_at ('u', integer times within 2^42 ms of 1970). Each key
-- has slots: the workspace, group and flags (unresolved, ai, snoozed) with none, one or all five of status category,
-- status, assignee, priority and channel, the status category and assignee together ('sa'), or with the status too
-- ('sia'); the status and the priority slots also keep the status category. A request naming the columns of one slot sums a handful of rows, and
-- a page sorted by status or priority counts each status or priority it walks (inbox-sort-groups.ts). A range of
-- time buckets is summed through inbox_counts_range, which seeks the slot's columns before the bucket.
-- inbox_subject_search is a trigram index of the entries' subjects as the subject filter compares them (SQLite's
-- lower(), case-sensitive, so a phrase of three or more characters is exactly that substring), with each
-- entry's workspace, over a view carrying every entry column, so a subject condition reads its matches only.
CREATE TABLE inbox_unread_tallies(user_id TEXT NOT NULL,project_id TEXT NOT NULL,group_id TEXT,assigned_to TEXT,unresolved INTEGER NOT NULL,counts_open INTEGER NOT NULL,ai INTEGER NOT NULL,snoozed INTEGER NOT NULL,total INTEGER NOT NULL);
INSERT INTO inbox_unread_tallies(user_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,snoozed,total) SELECT user_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,snoozed,count(*) FROM inbox_unread GROUP BY user_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,snoozed;
CREATE INDEX inbox_unread_tallies_key ON inbox_unread_tallies(user_id,project_id,counts_open,unresolved,ai,snoozed,assigned_to,group_id);
CREATE TABLE inbox_facets(kind TEXT NOT NULL,ref TEXT NOT NULL,value,conversation_id TEXT NOT NULL,project_id TEXT NOT NULL,group_id TEXT,assigned_to TEXT,status_category TEXT,priority TEXT,channel TEXT,status_id TEXT,created_at INTEGER,updated_at INTEGER,sort_at INTEGER,unresolved INTEGER NOT NULL,ai INTEGER NOT NULL,snoozed INTEGER NOT NULL,tags_key TEXT);
INSERT INTO inbox_facets(kind,ref,value,conversation_id,project_id,group_id,assigned_to,status_category,priority,channel,status_id,created_at,updated_at,sort_at,unresolved,ai,snoozed,tags_key) SELECT 't',t.value,NULL,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.status_category,e.priority,e.channel,e.status_id,e.created_at,e.updated_at,e.sort_at,e.unresolved,e.ai,e.snoozed,e.tags_key FROM inbox_entries e JOIN json_each(e.tags_key) t UNION ALL SELECT 'f',v.field_id,json_extract(v.value_json,'$'),e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.status_category,e.priority,e.channel,e.status_id,e.created_at,e.updated_at,e.sort_at,e.unresolved,e.ai,e.snoozed,e.tags_key FROM inbox_entries e JOIN ticket_field_values v ON v.project_id=e.project_id AND v.conversation_id=e.conversation_id WHERE json_valid(v.value_json,6) AND json_extract(v.value_json,'$') IS NOT NULL UNION ALL SELECT 'n',v.field_id,CASE WHEN json_extract(v.value_json,'$')='' THEN '' END,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.status_category,e.priority,e.channel,e.status_id,e.created_at,e.updated_at,e.sort_at,e.unresolved,e.ai,e.snoozed,e.tags_key FROM inbox_entries e JOIN ticket_field_values v ON v.project_id=e.project_id AND v.conversation_id=e.conversation_id WHERE json_valid(v.value_json,6) AND json_extract(v.value_json,'$') IS NOT NULL UNION ALL SELECT 'w','',NULL,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.status_category,e.priority,e.channel,e.status_id,e.created_at,e.updated_at,e.sort_at,e.unresolved,e.ai,e.snoozed,e.tags_key FROM inbox_entries e WHERE json_array_length(e.tags_key)>8;
CREATE TABLE inbox_counts(family TEXT NOT NULL,k1 TEXT NOT NULL,k2 NOT NULL,slot TEXT NOT NULL,project_id TEXT NOT NULL,group_id TEXT,unresolved INTEGER NOT NULL,ai INTEGER NOT NULL,snoozed INTEGER NOT NULL,status_category TEXT,status_id TEXT,assigned_to TEXT,priority TEXT,channel TEXT,total INTEGER NOT NULL);
INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END,count(*) FROM (SELECT 'a' family,'' k1,'' k2,e.* FROM inbox_entries e) JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl GROUP BY family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END;
INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END,count(*) FROM (SELECT 's' family,json_array(a.value) k1,'' k2,e.* FROM inbox_entries e JOIN json_each(e.tags_key) a WHERE json_array_length(e.tags_key)<=8 UNION ALL SELECT 's',json_array(a.value,b.value),'',e.* FROM inbox_entries e JOIN json_each(e.tags_key) a JOIN json_each(e.tags_key) b ON b.value>a.value WHERE json_array_length(e.tags_key)<=8 UNION ALL SELECT 's',json_array(a.value,b.value,c.value),'',e.* FROM inbox_entries e JOIN json_each(e.tags_key) a JOIN json_each(e.tags_key) b ON b.value>a.value JOIN json_each(e.tags_key) c ON c.value>b.value WHERE json_array_length(e.tags_key)<=8 UNION ALL SELECT 's',json_array(a.value,b.value,c.value,d.value),'',e.* FROM inbox_entries e JOIN json_each(e.tags_key) a JOIN json_each(e.tags_key) b ON b.value>a.value JOIN json_each(e.tags_key) c ON c.value>b.value JOIN json_each(e.tags_key) d ON d.value>c.value WHERE json_array_length(e.tags_key)<=8) JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl GROUP BY family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END;
INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END,count(*) FROM (SELECT 'c' family,'y' k1,CAST(strftime('%Y',(CASE WHEN e.created_at>=0 THEN e.created_at/86400000 ELSE (e.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0 k2,e.* FROM inbox_entries e WHERE (typeof(e.created_at)='integer' AND e.created_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'c' family,'m' k1,(CAST(strftime('%Y',(CASE WHEN e.created_at>=0 THEN e.created_at/86400000 ELSE (e.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN e.created_at>=0 THEN e.created_at/86400000 ELSE (e.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1) k2,e.* FROM inbox_entries e WHERE (typeof(e.created_at)='integer' AND e.created_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'c' family,'d' k1,(CASE WHEN e.created_at>=0 THEN e.created_at/86400000 ELSE (e.created_at+1)/86400000-1 END) k2,e.* FROM inbox_entries e WHERE (typeof(e.created_at)='integer' AND e.created_at BETWEEN -4398046511104 AND 4398046511104)) JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl GROUP BY family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END;
INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END,count(*) FROM (SELECT 'u' family,'y' k1,CAST(strftime('%Y',(CASE WHEN e.updated_at>=0 THEN e.updated_at/86400000 ELSE (e.updated_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0 k2,e.* FROM inbox_entries e WHERE (typeof(e.updated_at)='integer' AND e.updated_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'u' family,'m' k1,(CAST(strftime('%Y',(CASE WHEN e.updated_at>=0 THEN e.updated_at/86400000 ELSE (e.updated_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN e.updated_at>=0 THEN e.updated_at/86400000 ELSE (e.updated_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1) k2,e.* FROM inbox_entries e WHERE (typeof(e.updated_at)='integer' AND e.updated_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'u' family,'d' k1,(CASE WHEN e.updated_at>=0 THEN e.updated_at/86400000 ELSE (e.updated_at+1)/86400000-1 END) k2,e.* FROM inbox_entries e WHERE (typeof(e.updated_at)='integer' AND e.updated_at BETWEEN -4398046511104 AND 4398046511104)) JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl GROUP BY family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END;
INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END,count(*) FROM (SELECT 'v' family,f.ref k1,f.value k2,f.* FROM inbox_facets f WHERE f.kind='f' UNION ALL SELECT 'n',f.ref,'',f.* FROM inbox_facets f WHERE f.kind='f') JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl GROUP BY family,k1,k2,sl.value,project_id,group_id,unresolved,ai,snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN priority END,CASE WHEN sl.value IN ('*','channel') THEN channel END;
-- A facet's rows in each order a page walks: the inbox order, and a custom sort led by updated_at, created_at or
-- priority in the sort's own expression (tickets/sort.ts), then the newest conversation id first. A number field
-- compares CAST(value AS REAL) (tickets/filters.ts), so that has its own index too. Tag ids are unique across
-- workspaces, so a tag's rows are one range in each order on the all-workspaces door as well; a row's workspace,
-- group and flags are read from the row.
CREATE INDEX inbox_facets_conversation ON inbox_facets(conversation_id,kind,ref);
CREATE INDEX inbox_facets_order ON inbox_facets(kind,ref,value,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_facets_real ON inbox_facets(kind,ref,CAST(value AS REAL),sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_facets_by_updated_at_asc ON inbox_facets(kind,ref,value,CAST(updated_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_facets_by_updated_at_desc ON inbox_facets(kind,ref,value,CAST(updated_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_facets_by_created_at_asc ON inbox_facets(kind,ref,value,CAST(created_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_facets_by_created_at_desc ON inbox_facets(kind,ref,value,CAST(created_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_facets_by_priority_asc ON inbox_facets(kind,ref,value,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END,conversation_id DESC);
CREATE INDEX inbox_facets_by_priority_desc ON inbox_facets(kind,ref,value,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END DESC,conversation_id DESC);
-- A slot's rows of one key (or a range of time buckets), then the five columns a slot may keep, then the flags.
CREATE INDEX inbox_counts_key ON inbox_counts(project_id,family,slot,k1,k2,status_category,status_id,assigned_to,priority,channel,snoozed,unresolved,ai,group_id);
CREATE INDEX inbox_counts_real ON inbox_counts(project_id,family,slot,k1,CAST(k2 AS REAL),status_category,status_id,assigned_to,priority,channel,snoozed,unresolved,ai,group_id);
CREATE INDEX inbox_counts_range ON inbox_counts(project_id,family,slot,k1,status_category,assigned_to,status_id,priority,channel,k2,unresolved,ai,snoozed,group_id);
-- A page in the inbox order pinned to one status walks that status's entries, as 313 does for a status category.
CREATE INDEX inbox_entries_status_id_order ON inbox_entries(project_id,status_id,sort_at DESC,conversation_id DESC);
-- A time bound's page walks the page's order a week at a time, reading only the entries inside the bound: each index
-- holds an order's week (monotonic in the order's value) and then the bound's time.
CREATE INDEX inbox_entries_sort_week_created_at ON inbox_entries(project_id,(CASE WHEN typeof(sort_at) IN ('integer','real') THEN CAST(sort_at/604800000 AS INTEGER) END),CAST(created_at AS REAL));
CREATE INDEX inbox_entries_sort_week_updated_at ON inbox_entries(project_id,(CASE WHEN typeof(sort_at) IN ('integer','real') THEN CAST(sort_at/604800000 AS INTEGER) END),CAST(updated_at AS REAL));
CREATE INDEX inbox_entries_updated_week_created_at ON inbox_entries(project_id,CAST(CAST(updated_at AS REAL)/604800000 AS INTEGER),CAST(created_at AS REAL));
CREATE INDEX inbox_entries_created_week_updated_at ON inbox_entries(project_id,CAST(CAST(created_at AS REAL)/604800000 AS INTEGER),CAST(updated_at AS REAL));
-- A role that sees one group walks that group's entries and facets in the inbox order, and its time bounds a week at a time.
CREATE INDEX inbox_entries_group_order ON inbox_entries(project_id,group_id,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_group_status_order ON inbox_entries(project_id,group_id,status_category,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_facets_group_order ON inbox_facets(kind,ref,value,group_id,sort_at DESC,conversation_id DESC);
-- A group's own custom sorts led by updated_at, created_at or priority, for entries and facets alike.
CREATE INDEX inbox_entries_group_by_updated_at_asc ON inbox_entries(project_id,group_id,CAST(updated_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_facets_group_by_updated_at_asc ON inbox_facets(kind,ref,value,group_id,CAST(updated_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_group_by_updated_at_desc ON inbox_entries(project_id,group_id,CAST(updated_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_facets_group_by_updated_at_desc ON inbox_facets(kind,ref,value,group_id,CAST(updated_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_entries_group_by_created_at_asc ON inbox_entries(project_id,group_id,CAST(created_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_facets_group_by_created_at_asc ON inbox_facets(kind,ref,value,group_id,CAST(created_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_group_by_created_at_desc ON inbox_entries(project_id,group_id,CAST(created_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_facets_group_by_created_at_desc ON inbox_facets(kind,ref,value,group_id,CAST(created_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_entries_group_by_priority_asc ON inbox_entries(project_id,group_id,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END,conversation_id DESC);
CREATE INDEX inbox_facets_group_by_priority_asc ON inbox_facets(kind,ref,value,group_id,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END,conversation_id DESC);
CREATE INDEX inbox_entries_group_by_priority_desc ON inbox_entries(project_id,group_id,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END DESC,conversation_id DESC);
CREATE INDEX inbox_facets_group_by_priority_desc ON inbox_facets(kind,ref,value,group_id,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END DESC,conversation_id DESC);
-- A page of one status category in a custom sort led by updated_at, created_at or priority walks that status's
-- entries and facet rows in the sort's own order (a view of closed tickets reads closed rows only).
CREATE INDEX inbox_entries_status_by_updated_at_asc ON inbox_entries(project_id,status_category,CAST(updated_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_facets_status_by_updated_at_asc ON inbox_facets(kind,ref,value,status_category,CAST(updated_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_status_by_updated_at_desc ON inbox_entries(project_id,status_category,CAST(updated_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_facets_status_by_updated_at_desc ON inbox_facets(kind,ref,value,status_category,CAST(updated_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_entries_status_by_created_at_asc ON inbox_entries(project_id,status_category,CAST(created_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_facets_status_by_created_at_asc ON inbox_facets(kind,ref,value,status_category,CAST(created_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_status_by_created_at_desc ON inbox_entries(project_id,status_category,CAST(created_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_facets_status_by_created_at_desc ON inbox_facets(kind,ref,value,status_category,CAST(created_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_entries_status_by_priority_asc ON inbox_entries(project_id,status_category,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END,conversation_id DESC);
CREATE INDEX inbox_facets_status_by_priority_asc ON inbox_facets(kind,ref,value,status_category,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END,conversation_id DESC);
CREATE INDEX inbox_entries_status_by_priority_desc ON inbox_entries(project_id,status_category,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END DESC,conversation_id DESC);
CREATE INDEX inbox_facets_status_by_priority_desc ON inbox_facets(kind,ref,value,status_category,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END DESC,conversation_id DESC);
-- A facet's page of the inbox views' flags (resolved or not, AI or not, snoozed or not) walks those rows in the inbox order.
CREATE INDEX inbox_facets_flags_order ON inbox_facets(kind,ref,value,unresolved,ai,snoozed,sort_at DESC,conversation_id DESC);
-- A facet's page pinned to one status category or assignee walks only those rows, in the inbox order; so does a time bound's.
CREATE INDEX inbox_facets_status_category_order ON inbox_facets(kind,ref,value,status_category,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_facets_assigned_to_order ON inbox_facets(kind,ref,value,assigned_to,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_status_category_sort_week_created_at ON inbox_entries(project_id,status_category,(CASE WHEN typeof(sort_at) IN ('integer','real') THEN CAST(sort_at/604800000 AS INTEGER) END),CAST(created_at AS REAL));
CREATE INDEX inbox_entries_status_category_sort_week_updated_at ON inbox_entries(project_id,status_category,(CASE WHEN typeof(sort_at) IN ('integer','real') THEN CAST(sort_at/604800000 AS INTEGER) END),CAST(updated_at AS REAL));
CREATE INDEX inbox_entries_group_sort_week_created_at ON inbox_entries(project_id,group_id,(CASE WHEN typeof(sort_at) IN ('integer','real') THEN CAST(sort_at/604800000 AS INTEGER) END),CAST(created_at AS REAL));
CREATE INDEX inbox_entries_group_sort_week_updated_at ON inbox_entries(project_id,group_id,(CASE WHEN typeof(sort_at) IN ('integer','real') THEN CAST(sort_at/604800000 AS INTEGER) END),CAST(updated_at AS REAL));
-- Entries whose times the buckets do not hold (not an integer within 2^42 ms of 1970) are counted one by one.
CREATE INDEX inbox_entries_unbucketed_created_at ON inbox_entries(project_id,CAST(created_at AS REAL)) WHERE created_at IS NOT NULL AND NOT (typeof(created_at)='integer' AND created_at BETWEEN -4398046511104 AND 4398046511104);
CREATE INDEX inbox_entries_unbucketed_updated_at ON inbox_entries(project_id,CAST(updated_at AS REAL)) WHERE updated_at IS NOT NULL AND NOT (typeof(updated_at)='integer' AND updated_at BETWEEN -4398046511104 AND 4398046511104);
-- A page sorted by conversation id with a time bound merges the bound's 30-day blocks, each walked in id order
-- (inbox-merge.ts): ids may follow creation, so the bound's matches can lie at the far end of the id order. A page of
-- some status categories walks each category's blocks.
CREATE INDEX inbox_entries_created_block ON inbox_entries(project_id,CAST(CAST(created_at AS REAL)/2592000000 AS INTEGER),conversation_id DESC);
CREATE INDEX inbox_entries_updated_block ON inbox_entries(project_id,CAST(CAST(updated_at AS REAL)/2592000000 AS INTEGER),conversation_id DESC);
CREATE INDEX inbox_entries_created_status_block ON inbox_entries(project_id,status_category,CAST(CAST(created_at AS REAL)/2592000000 AS INTEGER),conversation_id DESC);
CREATE INDEX inbox_entries_updated_status_block ON inbox_entries(project_id,status_category,CAST(CAST(updated_at AS REAL)/2592000000 AS INTEGER),conversation_id DESC);
CREATE VIEW inbox_entry_subjects AS SELECT rowid AS rowid,lower(subject) AS subject_text,'|'||project_id||'|' AS workspace,conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key FROM inbox_entries WHERE inbox_entries.subject IS NOT NULL AND inbox_entries.subject<>'';
CREATE VIRTUAL TABLE inbox_subject_search USING fts5(subject_text,workspace,conversation_id UNINDEXED,project_id UNINDEXED,contact_id UNINDEXED,company_id UNINDEXED,assigned_to UNINDEXED,group_id UNINDEXED,status_category UNINDEXED,priority UNINDEXED,channel UNINDEXED,status_id UNINDEXED,subject UNINDEXED,brand_id UNINDEXED,requester_id UNINDEXED,submitter_id UNINDEXED,submitter_type UNINDEXED,created_at UNINDEXED,updated_at UNINDEXED,ticket_version UNINDEXED,sort_at UNINDEXED,unresolved UNINDEXED,counts_open UNINDEXED,ai UNINDEXED,ai_profile UNINDEXED,snoozed UNINDEXED,contact_revision UNINDEXED,tags_key UNINDEXED,content='inbox_entry_subjects',content_rowid='rowid',tokenize='trigram case_sensitive 1');
INSERT INTO inbox_subject_search(inbox_subject_search,rank) VALUES('secure-delete',1);
INSERT INTO inbox_subject_search(inbox_subject_search) VALUES('rebuild');
-- A member's unread rows are inserted and deleted (313); each change moves the member's tally.
CREATE TRIGGER inbox_unread_counted AFTER INSERT ON inbox_unread BEGIN
 INSERT INTO inbox_unread_tallies(user_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,snoozed,total) SELECT NEW.user_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.snoozed,0 WHERE NOT EXISTS(SELECT 1 FROM inbox_unread_tallies WHERE inbox_unread_tallies.user_id=NEW.user_id AND inbox_unread_tallies.project_id=NEW.project_id AND inbox_unread_tallies.group_id IS NEW.group_id AND inbox_unread_tallies.assigned_to IS NEW.assigned_to AND inbox_unread_tallies.unresolved IS NEW.unresolved AND inbox_unread_tallies.counts_open IS NEW.counts_open AND inbox_unread_tallies.ai IS NEW.ai AND inbox_unread_tallies.snoozed IS NEW.snoozed);
 UPDATE inbox_unread_tallies SET total=total+1 WHERE inbox_unread_tallies.user_id=NEW.user_id AND inbox_unread_tallies.project_id=NEW.project_id AND inbox_unread_tallies.group_id IS NEW.group_id AND inbox_unread_tallies.assigned_to IS NEW.assigned_to AND inbox_unread_tallies.unresolved IS NEW.unresolved AND inbox_unread_tallies.counts_open IS NEW.counts_open AND inbox_unread_tallies.ai IS NEW.ai AND inbox_unread_tallies.snoozed IS NEW.snoozed;
END;
CREATE TRIGGER inbox_unread_uncounted AFTER DELETE ON inbox_unread BEGIN
 UPDATE inbox_unread_tallies SET total=total-1 WHERE inbox_unread_tallies.user_id=OLD.user_id AND inbox_unread_tallies.project_id=OLD.project_id AND inbox_unread_tallies.group_id IS OLD.group_id AND inbox_unread_tallies.assigned_to IS OLD.assigned_to AND inbox_unread_tallies.unresolved IS OLD.unresolved AND inbox_unread_tallies.counts_open IS OLD.counts_open AND inbox_unread_tallies.ai IS OLD.ai AND inbox_unread_tallies.snoozed IS OLD.snoozed;
 DELETE FROM inbox_unread_tallies WHERE total=0 AND inbox_unread_tallies.user_id=OLD.user_id AND inbox_unread_tallies.project_id=OLD.project_id AND inbox_unread_tallies.group_id IS OLD.group_id AND inbox_unread_tallies.assigned_to IS OLD.assigned_to AND inbox_unread_tallies.unresolved IS OLD.unresolved AND inbox_unread_tallies.counts_open IS OLD.counts_open AND inbox_unread_tallies.ai IS OLD.ai AND inbox_unread_tallies.snoozed IS OLD.snoozed;
END;
CREATE TRIGGER inbox_unread_recounted AFTER UPDATE ON inbox_unread BEGIN
 UPDATE inbox_unread_tallies SET total=total-1 WHERE inbox_unread_tallies.user_id=OLD.user_id AND inbox_unread_tallies.project_id=OLD.project_id AND inbox_unread_tallies.group_id IS OLD.group_id AND inbox_unread_tallies.assigned_to IS OLD.assigned_to AND inbox_unread_tallies.unresolved IS OLD.unresolved AND inbox_unread_tallies.counts_open IS OLD.counts_open AND inbox_unread_tallies.ai IS OLD.ai AND inbox_unread_tallies.snoozed IS OLD.snoozed;
 DELETE FROM inbox_unread_tallies WHERE total=0 AND inbox_unread_tallies.user_id=OLD.user_id AND inbox_unread_tallies.project_id=OLD.project_id AND inbox_unread_tallies.group_id IS OLD.group_id AND inbox_unread_tallies.assigned_to IS OLD.assigned_to AND inbox_unread_tallies.unresolved IS OLD.unresolved AND inbox_unread_tallies.counts_open IS OLD.counts_open AND inbox_unread_tallies.ai IS OLD.ai AND inbox_unread_tallies.snoozed IS OLD.snoozed;
 INSERT INTO inbox_unread_tallies(user_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,snoozed,total) SELECT NEW.user_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.snoozed,0 WHERE NOT EXISTS(SELECT 1 FROM inbox_unread_tallies WHERE inbox_unread_tallies.user_id=NEW.user_id AND inbox_unread_tallies.project_id=NEW.project_id AND inbox_unread_tallies.group_id IS NEW.group_id AND inbox_unread_tallies.assigned_to IS NEW.assigned_to AND inbox_unread_tallies.unresolved IS NEW.unresolved AND inbox_unread_tallies.counts_open IS NEW.counts_open AND inbox_unread_tallies.ai IS NEW.ai AND inbox_unread_tallies.snoozed IS NEW.snoozed);
 UPDATE inbox_unread_tallies SET total=total+1 WHERE inbox_unread_tallies.user_id=NEW.user_id AND inbox_unread_tallies.project_id=NEW.project_id AND inbox_unread_tallies.group_id IS NEW.group_id AND inbox_unread_tallies.assigned_to IS NEW.assigned_to AND inbox_unread_tallies.unresolved IS NEW.unresolved AND inbox_unread_tallies.counts_open IS NEW.counts_open AND inbox_unread_tallies.ai IS NEW.ai AND inbox_unread_tallies.snoozed IS NEW.snoozed;
END;
-- A facet's field value counts while the row exists.
-- Every count row a trigger moves is found by its whole key: the keys (s) and slots (sl) are joined before
-- inbox_counts (CROSS JOIN keeps that order), so inbox_counts_key seeks on (project_id, family, slot, k1, k2, ...)
-- and a write reads a few rows per key, however many counts the workspace holds.
CREATE TRIGGER inbox_facet_counted AFTER INSERT ON inbox_facets WHEN NEW.kind='f' BEGIN
 INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT s.family,s.k1,s.k2,sl.value,NEW.project_id,NEW.group_id,NEW.unresolved,NEW.ai,NEW.snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END,CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END,0 FROM (SELECT 'v' family,NEW.ref k1,NEW.value k2 UNION ALL SELECT 'n',NEW.ref,'') s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl WHERE NOT EXISTS(SELECT 1 FROM inbox_counts t WHERE t.project_id=NEW.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END AND t.snoozed=NEW.snoozed AND t.unresolved=NEW.unresolved AND t.ai=NEW.ai AND t.group_id IS NEW.group_id);
 UPDATE inbox_counts SET total=total+1 WHERE rowid IN (SELECT t.rowid FROM (SELECT 'v' family,NEW.ref k1,NEW.value k2 UNION ALL SELECT 'n',NEW.ref,'') s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl CROSS JOIN inbox_counts t ON t.project_id=NEW.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END AND t.snoozed=NEW.snoozed AND t.unresolved=NEW.unresolved AND t.ai=NEW.ai AND t.group_id IS NEW.group_id);
END;
CREATE TRIGGER inbox_facet_uncounted AFTER DELETE ON inbox_facets WHEN OLD.kind='f' BEGIN
 UPDATE inbox_counts SET total=total-1 WHERE rowid IN (SELECT t.rowid FROM (SELECT 'v' family,OLD.ref k1,OLD.value k2 UNION ALL SELECT 'n',OLD.ref,'') s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl CROSS JOIN inbox_counts t ON t.project_id=OLD.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN OLD.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN OLD.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN OLD.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN OLD.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN OLD.channel END AND t.snoozed=OLD.snoozed AND t.unresolved=OLD.unresolved AND t.ai=OLD.ai AND t.group_id IS OLD.group_id);
 DELETE FROM inbox_counts WHERE total=0 AND rowid IN (SELECT t.rowid FROM (SELECT 'v' family,OLD.ref k1,OLD.value k2 UNION ALL SELECT 'n',OLD.ref,'') s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl CROSS JOIN inbox_counts t ON t.project_id=OLD.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN OLD.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN OLD.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN OLD.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN OLD.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN OLD.channel END AND t.snoozed=OLD.snoozed AND t.unresolved=OLD.unresolved AND t.ai=OLD.ai AND t.group_id IS OLD.group_id);
END;
-- An entry brings its facets, tag sets, time buckets and subject; 313 deletes and re-inserts an entry on most changes.
CREATE TRIGGER inbox_entry_faceted AFTER INSERT ON inbox_entries BEGIN
 INSERT INTO inbox_facets(kind,ref,value,conversation_id,project_id,group_id,assigned_to,status_category,priority,channel,status_id,created_at,updated_at,sort_at,unresolved,ai,snoozed,tags_key) SELECT 't',t.value,NULL,NEW.conversation_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.status_category,NEW.priority,NEW.channel,NEW.status_id,NEW.created_at,NEW.updated_at,NEW.sort_at,NEW.unresolved,NEW.ai,NEW.snoozed,NEW.tags_key FROM json_each(NEW.tags_key) t UNION ALL SELECT 'f',v.field_id,json_extract(v.value_json,'$'),NEW.conversation_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.status_category,NEW.priority,NEW.channel,NEW.status_id,NEW.created_at,NEW.updated_at,NEW.sort_at,NEW.unresolved,NEW.ai,NEW.snoozed,NEW.tags_key FROM ticket_field_values v WHERE v.project_id=NEW.project_id AND v.conversation_id=NEW.conversation_id AND json_valid(v.value_json,6) AND json_extract(v.value_json,'$') IS NOT NULL UNION ALL SELECT 'n',v.field_id,CASE WHEN json_extract(v.value_json,'$')='' THEN '' END,NEW.conversation_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.status_category,NEW.priority,NEW.channel,NEW.status_id,NEW.created_at,NEW.updated_at,NEW.sort_at,NEW.unresolved,NEW.ai,NEW.snoozed,NEW.tags_key FROM ticket_field_values v WHERE v.project_id=NEW.project_id AND v.conversation_id=NEW.conversation_id AND json_valid(v.value_json,6) AND json_extract(v.value_json,'$') IS NOT NULL UNION ALL SELECT 'w','',NULL,NEW.conversation_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.status_category,NEW.priority,NEW.channel,NEW.status_id,NEW.created_at,NEW.updated_at,NEW.sort_at,NEW.unresolved,NEW.ai,NEW.snoozed,NEW.tags_key WHERE json_array_length(NEW.tags_key)>8;
 INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT s.family,s.k1,s.k2,sl.value,NEW.project_id,NEW.group_id,NEW.unresolved,NEW.ai,NEW.snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END,CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END,0 FROM (SELECT 'a' family,'' k1,'' k2 UNION ALL SELECT 'c' family,'y' k1,CAST(strftime('%Y',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0 k2 WHERE (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'c' family,'m' k1,(CAST(strftime('%Y',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1) k2 WHERE (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'c' family,'d' k1,(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END) k2 WHERE (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104)) s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl WHERE NOT EXISTS(SELECT 1 FROM inbox_counts t WHERE t.project_id=NEW.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END AND t.snoozed=NEW.snoozed AND t.unresolved=NEW.unresolved AND t.ai=NEW.ai AND t.group_id IS NEW.group_id);
 UPDATE inbox_counts SET total=total+1 WHERE rowid IN (SELECT t.rowid FROM (SELECT 'a' family,'' k1,'' k2 UNION ALL SELECT 'c' family,'y' k1,CAST(strftime('%Y',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0 k2 WHERE (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'c' family,'m' k1,(CAST(strftime('%Y',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1) k2 WHERE (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104) UNION ALL SELECT 'c' family,'d' k1,(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END) k2 WHERE (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104)) s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl CROSS JOIN inbox_counts t ON t.project_id=NEW.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END AND t.snoozed=NEW.snoozed AND t.unresolved=NEW.unresolved AND t.ai=NEW.ai AND t.group_id IS NEW.group_id);
 INSERT INTO inbox_counts(family,k1,k2,slot,project_id,group_id,unresolved,ai,snoozed,status_category,status_id,assigned_to,priority,channel,total) SELECT s.family,s.k1,s.k2,sl.value,NEW.project_id,NEW.group_id,NEW.unresolved,NEW.ai,NEW.snoozed,CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END,CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END,CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN NEW.assigned_to END,CASE WHEN sl.value IN ('*','priority') THEN NEW.priority END,CASE WHEN sl.value IN ('*','channel') THEN NEW.channel END,0 FROM (SELECT 's' family,json_array(a.value) k1,'' k2 FROM json_each(NEW.tags_key) a WHERE json_array_length(NEW.tags_key)<=8 UNION ALL SELECT 's',json_array(a.value,b.value),'' FROM json_each(NEW.tags_key) a JOIN json_each(NEW.tags_key) b ON b.value>a.value WHERE json_array_length(NEW.tags_key)<=8 UNION ALL SELECT 's',json_array(a.value,b.value,c.value),'' FROM json_each(NEW.tags_key) a JOIN json_each(NEW.tags_key) b ON b.value>a.value JOIN json_each(NEW.tags_key) c ON c.value>b.value WHERE json_array_length(NEW.tags_key)<=8 UNION ALL SELECT 's',json_array(a.value,b.value,c.value,d.value),'' FROM json_each(NEW.tags_key) a JOIN json_each(NEW.tags_key) b ON b.value>a.value JOIN json_each(NEW.tags_key) c ON c.value>b.value JOIN json_each(NEW.tags_key) d ON d.value>c.value WHERE json_array_length(NEW.tags_key)<=8) s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl WHERE NOT EXISTS(SELECT 1 FROM inbox_counts t WHERE t.project_id=NEW.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN NEW.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN NEW.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','s