END;
CREATE TRIGGER inbox_entry_regrouped AFTER UPDATE OF conversation_id,project_id,group_id,assigned_to,unresolved,ai,snoozed,priority,status_category,channel,status_id ON inbox_entries WHEN NEW.conversation_id IS NOT OLD.conversation_id OR NEW.project_id IS NOT OLD.project_id OR NEW.group_id IS NOT OLD.group_id OR NEW.assigned_to IS NOT OLD.assigned_to OR NEW.unresolved IS NOT OLD.unresolved OR NEW.ai IS NOT OLD.ai OR NEW.snoozed IS NOT OLD.snoozed OR NEW.priority IS NOT OLD.priority OR NEW.status_category IS NOT OLD.status_category OR NEW.channel IS NOT OLD.channel OR NEW.status_id IS NOT OLD.status_id BEGIN
