CREATE TRIGGER inbox_entry_resubjected AFTER UPDATE OF subject,project_id ON inbox_entries WHEN NEW.subject IS NOT OLD.subject OR NEW.project_id IS NOT OLD.project_id BEGIN
 INSERT INTO inbox_subject_search(inbox_subject_search,rowid,subject_text,workspace) SELECT 'delete',OLD.rowid,lower(OLD.subject),'|'||OLD.project_id||'|' WHERE OLD.subject IS NOT NULL AND OLD.subject<>'';
 INSERT INTO inbox_subject_search(rowid,subject_text,workspace) SELECT NEW.rowid,lower(NEW.subject),'|'||NEW.project_id||'|' WHERE NEW.subject IS NOT NULL AND NEW.subject<>'';
END;
-- A custom field value set, changed or cleared (a deleted field or conversation cascades here) replaces its facet.
CREATE TRIGGER inbox_value_set AFTER INSERT ON ticket_field_values BEGIN
 DELETE FROM inbox_facets WHERE conversation_id=NEW.conversation_id AND kind IN ('f','n') AND ref=NEW.field_id AND project_id=NEW.project_id;
 INSERT INTO inbox_facets(kind,ref,value,conversation_id,project_id,group_id,assigned_to,status_category,priority,channel,status_id,created_at,updated_at,sort_at,unresolved,ai,snoozed,tags_key) SELECT k.kind,NEW.field_id,iif(k.kind='f',json_extract(NEW.value_json,'$'),CASE WHEN json_extract(NEW.value_json,'$')='' THEN '' END),e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.status_category,e.priority,e.channel,e.status_id,e.created_at,e.updated_at,e.sort_at,e.unresolved,e.ai,e.snoozed,e.tags_key FROM inbox_entries e JOIN (SELECT 'f' kind UNION ALL SELECT 'n') k WHERE e.conversation_id=NEW.conversation_id AND e.project_id=NEW.project_id AND json_valid(NEW.value_json,6) AND json_extract(NEW.value_json,'$') IS NOT NULL;
END;
CREATE TRIGGER inbox_value_changed AFTER UPDATE ON ticket_field_values BEGIN
 DELETE FROM inbox_facets WHERE conversation_id=OLD.conversation_id AND kind IN ('f','n') AND ref=OLD.field_id AND project_id=OLD.project_id;
 DELETE FROM inbox_facets WHERE conversation_id=NEW.conversation_id AND kind IN ('f','n') AND ref=NEW.field_id AND project_id=NEW.project_id;
 INSERT INTO inbox_facets(kind,ref,value,conversation_id,project_id,group_id,assigned_to,status_category,priority,channel,status_id,created_at,updated_at,sort_at,unresolved,ai,snoozed,tags_key) SELECT k.kind,NEW.field_id,iif(k.kind='f',json_extract(NEW.value_json,'$'),CASE WHEN json_extract(NEW.value_json,'$')='' THEN '' END),e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.status_category,e.priority,e.channel,e.status_id,e.created_at,e.updated_at,e.sort_at,e.unresolved,e.ai,e.snoozed,e.tags_key FROM inbox_entries e JOIN (SELECT 'f' kind UNION ALL SELECT 'n') k WHERE e.conversation_id=NEW.conversation_id AND e.project_id=NEW.project_id AND json_valid(NEW.value_json,6) AND json_extract(NEW.value_json,'$') IS NOT NULL;
END;
CREATE TRIGGER inbox_value_cleared AFTER DELETE ON ticket_field_values BEGIN
 DELETE FROM inbox_facets WHERE conversation_id=OLD.conversation_id AND kind IN ('f','n') AND ref=OLD.field_id AND project_id=OLD.project_id;
END;
